// Package server implements the kvhttp HTTP API on top of a store.Store.
package server

import (
	"bytes"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

const (
	// MaxValueSize is the largest value, in bytes, a client may store.
	MaxValueSize = 1 << 20
	// MaxKeyLen is the longest permitted key.
	MaxKeyLen = 64

	// maxDrain bounds how much of an oversized body is read and discarded
	// before replying, so the client sees the 413 instead of a reset.
	maxDrain = 4 * MaxValueSize

	kvPrefix = "/kv/"
)

// Handler serves the key-value API.
type Handler struct {
	store *store.Store
}

// New returns a Handler backed by s.
func New(s *store.Store) *Handler {
	return &Handler{store: s}
}

// ServeHTTP routes on the raw request target so that percent-encoded
// characters are never decoded into something that looks like a valid key.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.RequestURI
	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			status(w, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "text/plain")
		writeBody(w, []byte("ok"))
	case path == "/kv":
		if r.Method != http.MethodGet {
			status(w, http.StatusMethodNotAllowed)
			return
		}
		h.list(w)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !ValidKey(key) {
			status(w, http.StatusBadRequest)
			return
		}
		h.key(w, r, key)
	default:
		status(w, http.StatusNotFound)
	}
}

func (h *Handler) list(w http.ResponseWriter) {
	body, err := json.Marshal(h.store.Keys())
	if err != nil {
		status(w, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	writeBody(w, body)
}

func (h *Handler) key(w http.ResponseWriter, r *http.Request, key string) {
	switch r.Method {
	case http.MethodGet:
		v, ok := h.store.Get(key)
		if !ok {
			status(w, http.StatusNotFound)
			return
		}
		w.Header().Set("Content-Type", "application/octet-stream")
		writeBody(w, v)
	case http.MethodPut:
		value, err := readValue(r)
		if err != nil {
			if errors.Is(err, errTooLarge) {
				status(w, http.StatusRequestEntityTooLarge)
			} else {
				status(w, http.StatusBadRequest)
			}
			return
		}
		if h.store.Put(key, value) {
			status(w, http.StatusCreated)
		} else {
			status(w, http.StatusOK)
		}
	case http.MethodDelete:
		if h.store.Delete(key) {
			status(w, http.StatusNoContent)
		} else {
			status(w, http.StatusNotFound)
		}
	default:
		status(w, http.StatusMethodNotAllowed)
	}
}

var errTooLarge = errors.New("value too large")

// readValue reads the request body, rejecting anything over MaxValueSize.
// Oversized bodies are partially drained so the error response is delivered
// cleanly rather than lost to a connection reset.
func readValue(r *http.Request) ([]byte, error) {
	if r.ContentLength > MaxValueSize {
		drain(r.Body)
		return nil, errTooLarge
	}
	var buf bytes.Buffer
	if r.ContentLength > 0 {
		// Room for the whole body plus the final read that observes EOF.
		buf.Grow(int(r.ContentLength) + bytes.MinRead)
	}
	if _, err := buf.ReadFrom(io.LimitReader(r.Body, MaxValueSize+1)); err != nil {
		return nil, err
	}
	b := buf.Bytes()
	if len(b) > MaxValueSize {
		drain(r.Body)
		return nil, errTooLarge
	}
	return b, nil
}

func drain(r io.Reader) {
	_, _ = io.CopyN(io.Discard, r, maxDrain)
}

// ValidKey reports whether k matches [A-Za-z0-9_-]{1,64}.
func ValidKey(k string) bool {
	if len(k) == 0 || len(k) > MaxKeyLen {
		return false
	}
	for i := 0; i < len(k); i++ {
		c := k[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func status(w http.ResponseWriter, code int) {
	if code != http.StatusNoContent {
		w.Header().Set("Content-Length", "0")
	}
	w.WriteHeader(code)
}

func writeBody(w http.ResponseWriter, body []byte) {
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write(body)
}

package server

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"kvhttp/internal/store"
)

func do(t *testing.T, h http.Handler, method, target string, body []byte) *http.Response {
	t.Helper()
	var r io.Reader
	if body != nil {
		r = bytes.NewReader(body)
	}
	req := httptest.NewRequest(method, target, r)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec.Result()
}

func TestRoutes(t *testing.T) {
	h := New(store.New())
	big := bytes.Repeat([]byte{0xff}, MaxValueSize)
	tests := []struct {
		method, target string
		body           []byte
		want           int
		wantBody       string
	}{
		{"GET", "/health", nil, 200, "ok"},
		{"POST", "/health", nil, 405, ""},
		{"GET", "/kv", nil, 200, "[]"},
		{"POST", "/kv", nil, 405, ""},
		{"GET", "/kv/a", nil, 404, ""},
		{"PUT", "/kv/a", []byte("hello"), 201, ""},
		{"PUT", "/kv/a", []byte("world"), 200, ""},
		{"GET", "/kv/a", nil, 200, "world"},
		{"PUT", "/kv/empty", nil, 201, ""},
		{"GET", "/kv/empty", nil, 200, ""},
		{"PUT", "/kv/big", big, 201, ""},
		{"PUT", "/kv/big", append(big, 0), 413, ""},
		{"GET", "/kv", nil, 200, `["a","big","empty"]`},
		{"PATCH", "/kv/a", nil, 405, ""},
		{"DELETE", "/kv/a", nil, 204, ""},
		{"DELETE", "/kv/a", nil, 404, ""},
		{"GET", "/kv/", nil, 400, ""},
		{"GET", "/kv/bad.key", nil, 400, ""},
		{"GET", "/kv/a/b", nil, 400, ""},
		{"GET", "/kv/%41", nil, 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), nil, 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 64), nil, 404, ""},
		{"GET", "/nope", nil, 404, ""},
		{"GET", "/", nil, 404, ""},
	}
	for _, tt := range tests {
		res := do(t, h, tt.method, tt.target, tt.body)
		got, _ := io.ReadAll(res.Body)
		if res.StatusCode != tt.want {
			t.Errorf("%s %s: status %d, want %d", tt.method, tt.target, res.StatusCode, tt.want)
		}
		if tt.wantBody != "" && string(got) != tt.wantBody {
			t.Errorf("%s %s: body %q, want %q", tt.method, tt.target, got, tt.wantBody)
		}
	}
	res := do(t, h, "GET", "/kv/big", nil)
	got, _ := io.ReadAll(res.Body)
	if !bytes.Equal(got, big) {
		t.Errorf("GET /kv/big returned %d bytes, want %d", len(got), len(big))
	}
	if ct := do(t, h, "GET", "/kv", nil).Header.Get("Content-Type"); ct != "application/json" {
		t.Errorf("list content-type %q", ct)
	}
}

// Package store provides a concurrency-safe in-memory key-value store.
package store

import (
	"slices"
	"sync"
)

// Store maps string keys to immutable byte values. The zero value is not
// usable; create one with New.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// New returns an empty Store.
func New() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores value under key and reports whether the key was new. The store
// takes ownership of value: the caller must not modify it afterwards.
func (s *Store) Put(key string, value []byte) (created bool) {
	if value == nil {
		value = []byte{}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = value
	return !exists
}

// Get returns the value stored under key. The returned slice must not be
// modified; values are shared between readers.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	delete(s.data, key)
	return ok
}

// Keys returns every key, sorted ascending by byte value. The result is
// never nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

package store

import (
	"slices"
	"testing"
)

func TestStore(t *testing.T) {
	s := New()
	if !s.Put("b", []byte("1")) {
		t.Fatal("first put should create")
	}
	if s.Put("b", []byte("2")) {
		t.Fatal("second put should replace")
	}
	s.Put("a", nil)
	if v, ok := s.Get("b"); !ok || string(v) != "2" {
		t.Fatalf("get b = %q, %v", v, ok)
	}
	if v, ok := s.Get("a"); !ok || len(v) != 0 {
		t.Fatalf("get a = %q, %v", v, ok)
	}
	if got := s.Keys(); !slices.Equal(got, []string{"a", "b"}) {
		t.Fatalf("keys = %v", got)
	}
	if !s.Delete("a") || s.Delete("a") {
		t.Fatal("delete should succeed exactly once")
	}
	if _, ok := s.Get("a"); ok {
		t.Fatal("a should be gone")
	}
}

// Command kvhttp is an HTTP/1.1 in-memory key-value server.
//
// Usage:
//
//	app <port>
//
// It listens on 127.0.0.1:<port> and serves until terminated.
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/server"
	"kvhttp/internal/store"
)

const (
	ioTimeout      = 30 * time.Second
	maxHeaderBytes = 16 << 10
	shutdownGrace  = 5 * time.Second
)

func main() {
	if len(os.Args) != 2 {
		usage()
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil || port == 0 {
		usage()
	}
	if err := run(uint16(port)); err != nil {
		log.Fatal(err)
	}
}

func usage() {
	fmt.Fprintf(os.Stderr, "usage: %s <port>\n", os.Args[0])
	os.Exit(2)
}

func run(port uint16) error {
	addr := net.JoinHostPort("127.0.0.1", strconv.Itoa(int(port)))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           server.New(store.New()),
		ReadHeaderTimeout: ioTimeout,
		ReadTimeout:       ioTimeout,
		WriteTimeout:      ioTimeout,
		IdleTimeout:       ioTimeout,
		MaxHeaderBytes:    maxHeaderBytes,
		ErrorLog:          log.New(os.Stderr, "kvhttp: ", log.LstdFlags),
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownGrace)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return err
	}
	if err := <-errc; !errors.Is(err, http.ErrServerClosed) {
		return err
	}
	return nil
}
